"use client";

import { useState } from "react";
import type { CartItem } from "@/lib/styleCart";

// Shelf zone classification
function getShelfZone(item: CartItem): "in" | "out" | "other" {
  if (item.product_type === "fake_hair") return "out";
  if (item.product_type === "tool") return "out";
  if (item.product_type === "tutorial") return "other";
  // Check secondary_category_labels first — set by the shelf seed with the
  // canonical category slug label so zone routing is always reliable.
  const labels = (item.secondary_category_labels ?? []).map((l) => l.toLowerCase());
  if (labels.some((l) => l === "shampoo" || l === "conditioner" || l === "deep conditioner")) return "in";
  if (labels.some((l) => l === "leave-in" || l === "styler" || l === "oil")) return "out";
  // Fall back to product name heuristic
  const name = item.product_name.toLowerCase();
  if (name.includes("shampoo") || name.includes("wash")) return "in";
  if (name.includes("conditioner") || name.includes("mask") || name.includes("treatment")) return "in";
  if (name.includes("leave") || name.includes("styler") || name.includes("gel") ||
      name.includes("oil") || name.includes("cream") || name.includes("mousse") ||
      name.includes("spray") || name.includes("serum")) return "out";
  return "out";
}

// Embedded shelf photography (served as data URIs so no extra fetch is needed)
const CABINET_IMG = "data:image/jpeg;base64,";
const NICHE_IMG = "data:image/jpeg;base64,";

// ─── Shelf item ───────────────────────────────────────────────────────────────
function ShelfItem({ item, onToggle }: { item: CartItem; onToggle: () => void }) {
  const isPurchased = item.status === "purchased";
  const isFakeHair = item.product_type === "fake_hair";
  const isTool = item.product_type === "tool";
  const buyUrl = item.affiliate_url ?? item.seller_url;
  const [imgFailed, setImgFailed] = useState(false);
  const hasPhoto = !!item.image_url && !imgFailed;

  const BottleShape = isTool ? ToolIcon : isFakeHair ? FakeHairIcon : BottleIcon;

  return (
    <div className="ssc-item" style={{ opacity: isPurchased ? 0.45 : 1 }}>
      <a
        href={buyUrl}
        target="_blank"
        rel="noopener noreferrer"
        className="ssc-item-link"
        aria-label={"Buy " + item.product_name}
      >
        {hasPhoto ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={item.image_url!}
            alt={item.product_name}
            onError={() => setImgFailed(true)}
            className="ssc-product-img"
          />
        ) : (
          <BottleShape score={item.compat_score} purchased={isPurchased} />
        )}
        <p className="ssc-product-name">
          {item.product_name.length > 20
            ? item.product_name.slice(0, 18) + "…"
            : item.product_name}
        </p>
        {item.price_estimate != null && (
          <p className="ssc-product-price">
            {"$" + item.price_estimate.toFixed(0)}
          </p>
        )}
      </a>
      <button
        type="button"
        onClick={onToggle}
        aria-label={isPurchased ? "Mark not got" : "Mark got it"}
        className={"ssc-check" + (isPurchased ? " ssc-check--done" : "")}
      >
        ✓
      </button>
    </div>
  );
}

// ─── Icons ────────────────────────────────────────────────────────────────────
function BottleIcon({ score, purchased }: { score: number | null; purchased: boolean }) {
  const fill = purchased ? "#D4CFC8" : score != null && score >= 70 ? "#B8D4C0" : score != null && score >= 40 ? "#D4C8A8" : "#C4BEB4";
  return (
    <svg width="52" height="90" viewBox="0 0 28 52" fill="none">
      <rect x="9" y="0" width="10" height="7" rx="2" fill="#1A1A1A" opacity={purchased ? 0.3 : 0.7} />
      <rect x="11" y="6" width="6" height="6" fill={fill} />
      <rect x="4" y="11" width="20" height="36" rx="3" fill={fill} />
      <rect x="6" y="18" width="16" height="18" rx="1" fill="white" fillOpacity="0.45" />
      {score != null && (
        <circle cx="14" cy="27" r="4" fill={score >= 70 ? "#2d7a3d" : score >= 40 ? "#c4831a" : "#b03030"} fillOpacity={purchased ? 0.4 : 0.9} />
      )}
    </svg>
  );
}

function ToolIcon({ purchased }: { score: number | null; purchased: boolean }) {
  const fill = purchased ? "#D4CFC8" : "#1A1A1A";
  const opacity = purchased ? 0.3 : 0.6;
  return (
    <svg width="52" height="90" viewBox="0 0 28 52" fill="none">
      <rect x="10" y="30" width="8" height="22" rx="4" fill={fill} opacity={opacity} />
      <ellipse cx="14" cy="20" rx="10" ry="12" fill={fill} opacity={opacity} />
      <rect x="8" y="8" width="2" height="8" rx="1" fill="white" opacity={purchased ? 0.1 : 0.3} />
      <rect x="13" y="6" width="2" height="10" rx="1" fill="white" opacity={purchased ? 0.1 : 0.3} />
      <rect x="18" y="8" width="2" height="8" rx="1" fill="white" opacity={purchased ? 0.1 : 0.3} />
    </svg>
  );
}

function FakeHairIcon({ purchased }: { score: number | null; purchased: boolean }) {
  const fill = purchased ? "#D4CFC8" : "#1A1A1A";
  const opacity = purchased ? 0.3 : 0.75;
  return (
    <svg width="52" height="90" viewBox="0 0 28 52" fill="none">
      <rect x="3" y="12" width="22" height="30" rx="2" fill={fill} opacity={opacity} />
      <rect x="1" y="8" width="26" height="8" rx="2" fill={fill} opacity={opacity * 1.1} />
      <rect x="12" y="8" width="4" height="34" fill="white" opacity={purchased ? 0.1 : 0.2} />
      <rect x="1" y="20" width="26" height="4" fill="white" opacity={purchased ? 0.1 : 0.2} />
    </svg>
  );
}

// ─── Photo shelf zone ─────────────────────────────────────────────────────────
// Renders items sitting on a photographic shelf image.
// The image is used as the section background; product rows are absolutely
// positioned to land on the shelf boards.
function PhotoShelf({
  label,
  sublabel,
  image,
  items,
  shelfOffsets, // top % positions of each shelf row inside the image
  rowPaddingLeft, // optional left padding % to shift items into a niche/inset
  onToggle,
}: {
  label: string;
  sublabel: string;
  image: string;
  items: CartItem[];
  shelfOffsets: number[]; // one per shelf row, 0-100 (percent from top of image)
  rowPaddingLeft?: string; // e.g. "40%" to push items into a niche area
  onToggle: (key: string) => void;
}) {
  const isEmpty = items.length === 0;

  // Distribute items across the available shelf rows
  const itemsPerRow = isEmpty ? 0 : Math.ceil(items.length / shelfOffsets.length);
  const rows: CartItem[][] = shelfOffsets.map((_, rowIdx) =>
    isEmpty ? [] : items.slice(rowIdx * itemsPerRow, (rowIdx + 1) * itemsPerRow)
  );

  return (
    <div className="ssc-photo-zone">
      <div className="ssc-zone-header">
        <span className="ssc-zone-label">{label}</span>
        <span className="ssc-zone-sublabel">{sublabel}</span>
      </div>
      <div className="ssc-photo-frame">
        {/* Background shelf photograph */}
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img src={image} alt="" aria-hidden className="ssc-shelf-bg" />
        {/* Empty-shelf overlay — shown when no products are assigned yet */}
        {isEmpty && (
          <div className="ssc-empty-overlay">
            <span className="ssc-empty-text">let&apos;s fill your shelf</span>
          </div>
        )}
        {/* Product rows sitting on each shelf */}
        {shelfOffsets.map((topPct, rowIdx) => {
          const rowItems = rows[rowIdx] ?? [];
          if (rowItems.length === 0) return null;
          return (
            <div
              key={rowIdx}
              className="ssc-shelf-row"
              style={{ top: topPct + "%", ...(rowPaddingLeft ? { paddingLeft: rowPaddingLeft } : {}) }}
            >
              {rowItems.map((item, i) => {
                const globalIdx = rowIdx * itemsPerRow + i;
                return (
                  <ShelfItem
                    key={item.product_id + "-" + globalIdx}
                    item={item}
                    onToggle={() => onToggle(item.product_id + "-" + globalIdx)}
                  />
                );
              })}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Tutorials ────────────────────────────────────────────────────────────────
function TutorialRow({ item }: { item: CartItem }) {
  const videoId = (() => {
    try { return new URL(item.tutorial_url ?? item.seller_url).searchParams.get("v"); }
    catch { return null; }
  })();
  return (
    <a href={item.tutorial_url ?? item.seller_url} target="_blank" rel="noopener noreferrer" className="ssc-tutorial-row">
      {videoId && (
        // eslint-disable-next-line @next/next/no-img-element
        <img src={"https://img.youtube.com/vi/" + videoId + "/mqdefault.jpg"} alt="" className="ssc-tutorial-thumb" />
      )}
      <div className="ssc-tutorial-text">
        <p className="ssc-tutorial-title">{item.product_name}</p>
        <p className="ssc-tutorial-sub">watch on youtube →</p>
      </div>
    </a>
  );
}

// ─── Main component ───────────────────────────────────────────────────────────
export default function ShowerShelfCart({
  cartId,
  items: initialItems,
}: {
  cartId: string;
  items: CartItem[];
}) {
  const [items, setItems] = useState(initialItems);
  const [shareState, setShareState] = useState<"idle" | "copied">("idle");

  function toggleItem(key: string) {
    setItems((prev) =>
      prev.map((item, i) => {
        if ((item.product_id + "-" + i) !== key) return item;
        return { ...item, status: item.status === "purchased" ? "pending" : "purchased" };
      })
    );
  }

  const tutorialItems = items.filter((i) => i.product_type === "tutorial");
  const purchasable = items.filter((i) => i.product_type !== "tutorial");
  const purchased = purchasable.filter((i) => i.status === "purchased");
  const total = purchasable.reduce((s, i) => s + (i.price_estimate ?? 0) * i.quantity, 0);
  const hasPrice = purchasable.some((i) => i.price_estimate != null);

  const inItems = items.filter((i) => getShelfZone(i) === "in" && i.product_type !== "tutorial");
  const outItems = items.filter((i) => getShelfZone(i) === "out" && i.product_type !== "tutorial");

  function handleGetEverything() {
    const remaining = purchasable.filter((i) => i.status !== "purchased");
    for (const item of remaining) {
      window.open(item.affiliate_url ?? item.seller_url, "_blank", "noopener,noreferrer");
    }
  }

  async function handleShare() {
    const url = window.location.origin + "/cart/" + cartId;
    try { await navigator.clipboard.writeText(url); } catch { /* denied */ }
    setShareState("copied");
    setTimeout(() => setShareState("idle"), 2200);
    fetch("/api/style-cart/" + cartId, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ checkout_status: "shared" }),
    }).catch(() => {});
  }

  return (
    <div className="ssc">
      <style>{`
        .ssc {
          font-family: var(--font-dm-sans, 'DM Sans', system-ui, sans-serif);
          background: #F7F5F2;
          padding-bottom: 80px;
        }

        /* ── Header ── */
        .ssc-header {
          background: #0a0a0a;
          padding: 24px 20px 20px;
        }
        .ssc-title {
          font-family: var(--font-lora, 'Lora', Georgia, serif);
          font-size: 22px;
          font-weight: 600;
          color: #F7F5F2;
          letter-spacing: -0.02em;
        }
        .ssc-subtitle {
          font-size: 10px;
          color: #666;
          margin-top: 4px;
        }
        .ssc-progress-track {
          margin-top: 14px;
          height: 2px;
          background: rgba(255,255,255,0.12);
          border-radius: 1px;
          overflow: hidden;
        }
        .ssc-progress-fill {
          height: 100%;
          background: #7BA7BC;
          border-radius: 1px;
          transition: width 0.4s ease;
        }
        .ssc-progress-label {
          font-size: 9px;
          color: #555;
          margin-top: 5px;
          text-align: right;
        }

        /* ── Zone layout ── */
        .ssc-zones {
          display: flex;
          flex-direction: column;
          gap: 32px;
          padding: 28px 16px;
          background: #F0EDEA;
        }

        .ssc-photo-zone {}

        .ssc-zone-header {
          display: flex;
          align-items: baseline;
          gap: 8px;
          margin-bottom: 10px;
          padding: 0 2px;
        }
        .ssc-zone-label {
          font-family: var(--font-lora, 'Lora', Georgia, serif);
          font-size: 12px;
          font-weight: 600;
          color: #1A1A1A;
        }
        .ssc-zone-sublabel {
          font-size: 9px;
          color: #888;
        }

        /* ── Photo frame: shelf image with products on it ── */
        .ssc-photo-frame {
          position: relative;
          width: 100%;
          border-radius: 6px;
          overflow: hidden;
          box-shadow: 0 4px 20px rgba(0,0,0,0.12);
        }
        /* Empty shelf overlay */
        .ssc-empty-overlay {
          position: absolute;
          inset: 0;
          display: flex;
          align-items: center;
          justify-content: center;
          background: rgba(255,255,255,0.45);
          backdrop-filter: blur(1px);
          pointer-events: none;
        }
        .ssc-empty-text {
          font-family: Georgia, serif;
          font-size: 15px;
          font-style: italic;
          color: rgba(0,0,0,0.55);
          letter-spacing: 0.01em;
          text-align: center;
          padding: 0 16px;
        }
        .ssc-shelf-bg {
          display: block;
          width: 100%;
          height: auto;
          object-fit: cover;
        }

        /* Row of products sitting on a shelf board */
        .ssc-shelf-row {
          position: absolute;
          left: 0;
          right: 0;
          transform: translateY(-100%);
          display: flex;
          flex-direction: row;
          align-items: flex-end;
          justify-content: center;
          gap: 16px;
          padding: 0 20px 8px;
        }

        /* ── Product item ── */
        .ssc-item {
          display: flex;
          flex-direction: column;
          align-items: center;
          transition: opacity 0.2s;
          min-width: 80px;
          max-width: 110px;
        }
        .ssc-item-link {
          display: flex;
          flex-direction: column;
          align-items: center;
          text-decoration: none;
        }
        .ssc-product-img {
          width: 72px;
          height: 90px;
          object-fit: contain;
          display: block;
          filter: drop-shadow(0 3px 8px rgba(0,0,0,0.22));
        }
        .ssc-product-name {
          margin-top: 5px;
          font-size: 10px;
          color: #2A2825;
          text-align: center;
          line-height: 1.3;
          word-break: break-word;
          hyphens: auto;
          text-shadow: 0 1px 3px rgba(255,255,255,0.9);
        }
        .ssc-product-price {
          font-size: 9px;
          color: #888;
          margin-top: 2px;
          text-align: center;
          text-shadow: 0 1px 2px rgba(255,255,255,0.8);
        }
        .ssc-check {
          margin-top: 5px;
          width: 22px;
          height: 22px;
          border-radius: 50%;
          border: 1.5px solid #C4BEB4;
          background: transparent;
          color: transparent;
          font-size: 11px;
          cursor: pointer;
          display: flex;
          align-items: center;
          justify-content: center;
          transition: all 0.15s;
          line-height: 1;
        }
        .ssc-check:hover { border-color: #1A1A1A; }
        .ssc-check--done {
          background: #7BA7BC;
          border-color: #7BA7BC;
          color: white;
        }

        /* ── Tutorials ── */
        .ssc-tutorials {
          padding: 20px 20px 0;
        }
        .ssc-tutorials-label {
          font-family: var(--font-lora, 'Lora', Georgia, serif);
          font-size: 11px;
          font-weight: 600;
          color: #1A1A1A;
          margin-bottom: 10px;
        }
        .ssc-tutorial-row {
          display: flex;
          align-items: center;
          gap: 12px;
          padding: 10px 0;
          border-bottom: 1px solid rgba(0,0,0,0.07);
          text-decoration: none;
        }
        .ssc-tutorial-thumb {
          width: 64px;
          height: 40px;
          object-fit: cover;
          border-radius: 3px;
          flex-shrink: 0;
        }
        .ssc-tutorial-title {
          font-size: 12px;
          color: #1A1A1A;
          font-weight: 500;
        }
        .ssc-tutorial-sub {
          font-size: 9px;
          color: #888;
          margin-top: 2px;
        }

        /* ── Store link ── */
        .ssc-store-link {
          margin: 20px 20px 0;
          display: flex;
          align-items: center;
          justify-content: space-between;
          border: 1px solid #E8E5E0;
          padding: 12px 16px;
          text-decoration: none;
          background: white;
          border-radius: 4px;
        }
        .ssc-store-link span:first-child { font-size: 11px; color: #1A1A1A; }
        .ssc-store-link span:last-child { font-size: 10px; color: #7BA7BC; }

        /* ── Fixed footer ── */
        .ssc-footer {
          position: fixed;
          bottom: 0; left: 0; right: 0;
          background: white;
          border-top: 1px solid #E8E5E0;
          padding: 12px 20px;
          display: flex;
          align-items: center;
          gap: 10px;
          z-index: 20;
        }
        .ssc-footer-price {
          font-family: var(--font-lora, 'Lora', Georgia, serif);
          font-size: 15px;
          font-weight: 600;
          color: #1A1A1A;
          flex: 1;
        }
        .ssc-footer-note {
          display: block;
          font-family: 'DM Sans', system-ui, sans-serif;
          font-size: 9px;
          font-weight: 400;
          color: #AAA;
          margin-top: 1px;
        }
        .ssc-btn-primary {
          background: #0a0a0a;
          color: #F7F5F2;
          border: none;
          padding: 10px 18px;
          font-size: 11px;
          font-weight: 600;
          cursor: pointer;
          border-radius: 2px;
          white-space: nowrap;
          transition: background 0.15s;
          text-decoration: none;
        }
        .ssc-btn-primary:hover { background: #333; }
        .ssc-btn-secondary {
          background: transparent;
          color: #1A1A1A;
          border: 1px solid #C4BEB4;
          padding: 10px 14px;
          font-size: 11px;
          font-weight: 500;
          cursor: pointer;
          border-radius: 2px;
          white-space: nowrap;
        }
        .ssc-btn-secondary:hover { border-color: #1A1A1A; }

        @media (prefers-reduced-motion: reduce) {
          .ssc-progress-fill { transition: none; }
        }
      `}</style>

      {/* Header */}
      <header className="ssc-header">
        <h1 className="ssc-title">my shelf</h1>
        <p className="ssc-subtitle">your routine · tap to mark got it · tap name to buy</p>
        {purchasable.length > 0 && (
          <>
            <div className="ssc-progress-track">
              <div
                className="ssc-progress-fill"
                style={{ width: ((purchased.length / purchasable.length) * 100) + "%" }}
              />
            </div>
            <p className="ssc-progress-label">{purchased.length}/{purchasable.length} got it</p>
          </>
        )}
      </header>

      {/* Shelf zones */}
      <div className="ssc-zones">
        {/* In-shower — white cabinet photo */}
        <PhotoShelf
          label="in the shower"
          sublabel="shampoo · conditioner · treatments"
          image={NICHE_IMG}
          items={inItems}
          shelfOffsets={[62, 82]}
          rowPaddingLeft="38%"
          onToggle={toggleItem}
        />

        {/* Out-of-shower — beige niche photo */}
        <PhotoShelf
          label="outside the shower"
          sublabel="leave-in · stylers · oils"
          image={CABINET_IMG}
          items={outItems}
          shelfOffsets={[48, 88]}
          onToggle={toggleItem}
        />
      </div>

      {/* Tutorials */}
      {tutorialItems.length > 0 && (
        <div className="ssc-tutorials">
          <p className="ssc-tutorials-label">tutorials</p>
          {tutorialItems.map((item, i) => (
            <TutorialRow key={i} item={item} />
          ))}
        </div>
      )}

      {/* Store link */}
      <a href="/store" className="ssc-store-link">
        <span>browse the full qoyl store</span>
        <span>shop →</span>
      </a>

      {/* Fixed footer */}
      <div className="ssc-footer">
        {items.length === 0 ? (
          <a href="/search" className="ssc-btn-primary" style={{ flex: 1, textAlign: "center" }}>
            search products to fill your shelf →
          </a>
        ) : (
          <>
            <div className="ssc-footer-price">
              {hasPrice ? "$" + total.toFixed(2) : "—"}
              <span className="ssc-footer-note">estimated · varies</span>
            </div>
            <button type="button" className="ssc-btn-secondary" onClick={handleShare}>
              {shareState === "copied" ? "copied ✓" : "share"}
            </button>
            <button type="button" className="ssc-btn-primary" onClick={handleGetEverything}>
              get remaining →
            </button>
          </>
        )}
      </div>
    </div>
  );
}
